package com.fregrance.app.service;  import java.time.LocalDate; import java.util.List;  import org.springframework.stereotype.Service;  import com.fregrance.app.dto.ReservationSlotResponse;  @Service public class ReservationSlotService {      public List<ReservationSlotResponse> findAvailableSlots(LocalDate date) {         return List.of(             buildSlot(date, "10:30", "recommended", "原口"),             buildSlot(date, "13:00", "open", "清水"),             buildSlot(date, "15:30", "open", "大塚")         );     }      private ReservationSlotResponse buildSlot(LocalDate date, String time, String status, String instructorName) {         String slotId = date + "_" + time.replace(":", "");         String label = date.getMonthValue() + "/" + date.getDayOfMonth() + " " + time;         return new ReservationSlotResponse(slotId, date.toString(), time, label, status, instructorName);     } }